import { resolveEffectiveRules } from "./rules/resolve.js";

async function reviewMem(path: string, opts: ReviewOptions = {}): Promise<ReviewResult> {
  const results = await review(path, { cwd: FIXTURES, ...opts });
20→  return results.find((r) => r.path === path) ?? results[0]!;
}

const FIXTURES = resolve(import.meta.dir, "../../test/fixtures/memory-files");

const NO_ADAPTERS: LoadResult = { sessions: [], adaptersDetected: [], skipped: {} };
const EMPTY_LOAD: LoadResult = { sessions: [], adaptersDetected: ["claude-code"], skipped: {} };
function emptyPrims(sessionId: string, agent: string) {
  return {
    sessionId,
30→    model: "unknown",
    agent,
    cwd: "/proj",
    toolCalls: [] as [],
    toolCallCounts: {},
    skillsInvoked: [] as string[],
    userMessages: [] as string[],
    userTurnCount: 0,
    assistantText: [] as string[],
  };
40→}

const SOME_SESSIONS: LoadResult = {
  sessions: [
    { agent: "claude-code", path: "/tmp/a.jsonl", mtime: Date.now(), primitives: emptyPrims("s1", "claude-code") },
    { agent: "cursor", path: "/tmp/b.jsonl", mtime: Date.now(), primitives: emptyPrims("s2", "cursor") },
  ],
  adaptersDetected: ["claude-code", "cursor"],
  skipped: {},
};
50→
/** Skip real session/judge I/O when a test only cares about another tier. */
const hermetic = { loadedSessions: NO_ADAPTERS };

async function withRules(
  overrides: Record<string, "on" | "off">,
  run: () => Promise<void>,
): Promise<void> {
  const home = mkdtempSync(join(tmpdir(), "dora-rules-"));
  const previous = process.env.DORAVAL_HOME;
60→  process.env.DORAVAL_HOME = home;
  writeFileSync(join(home, "config.yml"), [
    "journal:", "  repo: ''", "  projects: {}", "rules:", "  package: recommended", "  overrides:",
    ...Object.entries(overrides).map(([code, value]) => `    ${code}: ${value}`), "",
  ].join("\n"));
  try {
    await run();
  } finally {
    if (previous === undefined) delete process.env.DORAVAL_HOME;
    else process.env.DORAVAL_HOME = previous;
70→  }
}

